// sourceDeclaration converts one syntax declaration to verified model metadata.
func sourceDeclaration(declaration syntax.Node, packagePath string) *sourceModel {
	switch node := declaration.(type) {
	case *syntax.CheckedDecl:
		return &sourceModel{
			name:   node.Name.Name,
			fact:   checkedModel(packagePath, node.Name.Name),
			fields: nil, base: node.Base, variants: nil,
		}
	case *syntax.EnumDecl:
		variants := make([]string, 0, len(node.Variants))
		for _, variant := range node.Variants {
			variants = append(variants, variant.Name.Name)
		}
		return &sourceModel{
			name:   node.Name.Name,
			fact:   enumModel(packagePath, node.Name.Name, variants),
			fields: nil, base: nil, variants: node.Variants,
		}
	case *syntax.StructDecl:
		return &sourceModel{
			name: node.Name.Name, fact: nil, fields: node.Fields,
			base: nil, variants: nil,
		}
	default:
		return nil
	}
}

