func sameFields(source []*syntax.FieldDecl, generated *ast.FieldList) bool {
	flat := []sourceField(nil)
	for _, declaration := range source {
		if len(declaration.Field.Names) == 0 {
			flat = append(flat, sourceField{
				name: "", typeExpression: declaration.Field.Type, tag: declaration.Field.Tag,
			})
			continue
		}
		for _, name := range declaration.Field.Names {
			flat = append(flat, sourceField{
				name:           name.Name,
				typeExpression: declaration.Field.Type,
				tag:            declaration.Field.Tag,
			})
		}
	}
	if generated == nil || len(flat) != len(generated.List) {
		return false
	}
	for index, field := range flat {
		other := generated.List[index]
		if !sameExpression(field.typeExpression, other.Type) ||
			!sameExpression(field.tag, other.Tag) {
			return false
		}
		if field.name == "" && len(other.Names) == 0 {
			continue
		}
		if len(other.Names) != 1 || other.Names[0].Name != field.name {
			return false
		}
	}
	return true
}

func sameExpression(left ast.Expr, right ast.Expr) bool {
	leftNil := expressionNil(left)
	rightNil := expressionNil(right)
	if leftNil || rightNil {
		return leftNil && rightNil
	}
	leftText := new(bytes.Buffer)
	rightText := new(bytes.Buffer)
	if format.Node(leftText, token.NewFileSet(), left) != nil ||
		format.Node(rightText, token.NewFileSet(), right) != nil {
		return false
	}
	return leftText.String() == rightText.String()
}

func expressionNil(expression ast.Expr) bool {
	if expression == nil {
		return true
	}
	value := reflect.ValueOf(expression)
	return value.Kind() == reflect.Pointer && value.IsNil()
}
